INSERT INTO productos (id, codigo, ml, marca, nombre, precio, stock, stock_critico, categoria_id, familia, estacion, genero, tipo, concentracion, imagen, descripcion, hero_fondo, historia_titulo, historia, historia_imagen, cta_fondo, fondo_pagina, cta_titulo, cta_texto, nav_claro, hero_ajuste, humor, maridaje, notas, notas_imagenes, inspirado_en, colores) VALUES
  (1, 'LUX001', 90, 'Afnan', 'Turathi Blue for Men', 28000, 10, 2, 'moderados', 'acuatico', 'verano', 'hombre', 'arabe', 'edp', 'https://wonder.com.bo/wp-content/uploads/2025/05/turathi-afnan-notas.jpg', 'Una fragancia cítrica y amaderada ultra limpia, dominada por un vibrante pomelo jugoso sobre una base de ámbar sofisticado. Es un aroma fresco y elegante, ideal para el uso diario y la oficina, que destaca por su excelente duración en climas cálidos.', '/img/turathiblue/hero-turathi.jpg', 'LA ESENCIA DEL HORIZONTE', 'Turathi Blue nace del deseo de capturar la energía fresca y magnética del océano al atardecer. Creada para el hombre que abraza su elegancia natural con total confianza: una fragancia que fluye como una marea inagotable y se despliega en cada brisa marina, cada vibrante nota cítrica y cada instante de libertad frente al mar. Una firma olfativa pensada para quienes no solo navegan su propio camino, sino que dejan una huella imborrable a su paso.', '/img/turathiblue/fondo-notas.jpg', '/img/turathiblue/fondo-cta.jpg', '/img/turathiblue/fondo-seccion.jpg', 'Vive la Experiencia Turathi Blue', 'Eleva tu presencia con una fragancia fresca y magnética, hecha para deslumbrar bajo el atardecer y despertar tus sentidos.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","trabajo_reuniones"]', '{"salida":["Citricos"],"corazon":["Notas amaderadas","Ambar"],"fondo":["Almizcle blanco","Especias","Pachuli"]}', '{"salida":"/img/turathiblue/notas-salida.jpg","corazon":"/img/turathiblue/notas-corazon.jpg","fondo":"/img/turathiblue/notas-fondo.jpg"}', '{"marca":"Bvlgari","nombre":"Tygar","precioOriginal":476490}', '{"tema-bg":"#e4edf6","tema-card":"#c7c3bc","tema-dorado":"#d1860e","tema-card-salida":"#e6e3de","tema-card-corazon":"#e6e3de","tema-card-fondo":"#e6e3de"}'),
  (2, 'LUX002', 100, 'Afnan', '9pm', 25000, 8, 2, 'intensos', 'avainillado', 'invierno', 'hombre', 'arabe', 'edp', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTN1Yjy3dn9sLbw0SRYQokbFynHewjNF4R9Ex-GGHBwkVHUZXXsCM28v27m&s=10', 'Una fragancia dulce y seductora, dominada por una salida de manzana crujiente que evoluciona hacia una base densa de vainilla y canela. Es un aroma potente y magnético, ideal para fiestas y citas, que destaca por su proyección enorme y duración extrema en la noche.', '/img/9pm/hero-9pm.jpg', 'EL DOMINIO DE LA NOCHE', 'Afnan 9PM nace del deseo de capturar el magnetismo vibrante y seductor de las noches de invierno. Creada para el hombre que abraza su instinto y carisma con total confianza: una fragancia que resplandece como un fuego cálido en el frío y se despliega en cada rastro especiado, cada nota cremosa de vainilla y cada instante vibrante bajo la luz de la luna. Una firma olfativa pensada para quienes no solo viven la noche, sino que se convierten en los dueños absolutos de ella.', '/img/9pm/fondo-notas.jpg', '/img/9pm/fondo-cta.jpg', '/img/9pm/fondo-seccion.jpg', 'Vive la Experiencia 9PM', 'Eleva tu presencia con una fragancia cálida y seductora, hecha para deslumbrar en las noches de invierno y cautivar todos los sentidos.', NULL, 'contain', '["poderoso","romantico"]', '["cita_romantica","noche_especial"]', '{"salida":["Manzana","Canela","lavanda silvestre","bergamota"],"corazon":["Flor de azahar del naranjo","Lirio de los valles (muguete)"],"fondo":["Vainilla","Haba tonka","Ambar","Pachuli"]}', '{"salida":"/img/9pm/notas-salida.jpg","corazon":"/img/9pm/notas-corazon.jpg","fondo":"/img/9pm/notas-fondo.jpg"}', NULL, '{"tema-bg":"#000000","tema-card":"#95551f","tema-dorado":"#ffffff","tema-card-salida":"#401c0400","tema-card-corazon":"#401c0400","tema-card-fondo":"#401c0400"}'),
  (3, 'LUX003', 50, 'Dior', 'Miss Dior Eau de Parfum (2021)', 198400, 6, 2, 'moderados', 'floral', 'primavera', 'mujer', 'disenador', 'edp', 'https://media.falabella.com/falabellaCL/15535785_3/w=1200,h=1200,fit=pad', 'Una fragancia floral, elegante y romántica, con un carácter femenino y sofisticado.', '/img/missdior/hero-miss.jpg', 'EL ESPÍRITU DE LA PRIMAVERA', 'Miss Dior nace del deseo de capturar el encanto vibrante y luminoso de un jardín en flor. Creada para la mujer que abraza su romanticismo y alegría con total confianza: una fragancia que resplandece como un amanecer radiante y se despliega en cada estela floral, cada nota fresca de rosa y peonía, y cada instante rebosante de vida bajo la luz del sol. Una firma olfativa pensada para quienes no solo celebran el amor, sino que se convierten en la encarnación absoluta de él.', '/img/missdior/fondo-notas.jpg', '/img/missdior/fondo-cta.jpg', '/img/missdior/fondo-seccion.jpg', 'Vive la Experiencia Miss Dior', 'Eleva tu presencia con una fragancia floral y luminosa, hecha para deslumbrar como un jardín de primavera y cautivar todos los sentidos.', 1, 'contain', '["romantico","elegante"]', '["cita_romantica","noche_especial"]', '{"salida":["Iris","Peonía","Lirio de los valles (muguete)"],"corazon":["Rosa","Chabacano","Durazno"],"fondo":["Vainilla","Almizcle","Haba Tonka","Sandalo","Benjui"]}', '{"salida":"/img/missdior/notas-salida.jpg","corazon":"/img/missdior/notas-corazon.jpg","fondo":"/img/missdior/notas-fondo.jpg"}', NULL, '{"tema-bg":"#fcd0d0","tema-card":"#e5a5a4","tema-dorado":"#221919"}'),
  (4, 'LUX004', 100, 'Valentino', 'Donna Born In Roma', 159990, 4, 1, 'moderados', 'floral', 'primavera', 'mujer', 'disenador', 'edp', 'https://dbs.cl/media/catalog/product/v/a/valentino-vno-76144-4.jpg?optimize=low&bg-color=255,255,255&fit=bounds&height=&width=&canvas=:', 'Una fragancia de alta costura, cálida y floral con una vibrante mezcla de jazmín y vainilla Bourbon.', '/img/valen-donna/hero-donna.jpg', 'UNA CELEBRACIÓN DE LA FEMINIDAD MODERNA', 'Valentino Donna Born in Roma nace del deseo de capturar la energía vibrante y la dualidad de la cultura romana. Creada para la mujer que abraza su herencia con orgullo pero dicta sus propias reglas: una fragancia que fusiona la elegancia clásica de la alta costura con un espíritu vanguardista. Se despliega en un radiante corazón compuesto por un trío de jazmines, entrelazado con la envolvente calidez de la vainilla Bourbon y despertado por el toque atrevido de la grosella negra y la pimienta rosa. Una firma olfativa pensada para quienes no solo viven su individualidad, sino que la transforman en una declaración de estilo inconfundible.', '/img/valen-donna/fondo-notas.jpg', '/img/valen-donna/fondo-cta.jpg', '/img/valen-donna/fondo-seccion.jpg', 'Vive la Experiencia Donna Born in Roma', 'Eleva tu presencia con una fragancia vibrante y audaz, hecha para celebrar la feminidad moderna y cautivar todos los sentidos con un inconfundible toque de alta costura.', 1, 'contain', '["romantico","elegante"]', '["cita_romantica","noche_especial","dia_a_dia"]', '{"salida":["Grosellas negras","Pimienta rosa","Bergamota"],"corazon":["Jazmin","Jazmin sabac","Te del jazmin"],"fondo":["Vainilla Bourbon","Cachemira","Madera de gaiac"]}', '{"salida":"/img/valen-donna/notas-salida.jpg","corazon":"/img/valen-donna/notas-corazon.jpg","fondo":"/img/valen-donna/notas-fondo.jpg"}', NULL, '{"tema-bg":"#fcd0d0","tema-card":"#e5a5a4","tema-dorado":"#b7975c"}'),
  (5, 'LUX005', 100, 'Versace', 'Eros', 69990, 9, 2, 'moderados', 'avainillado', 'primavera', 'hombre', 'disenador', 'edt', 'https://fimgs.net/photogram/p1200/xu/dd/sjhF2oPsrTWGj1R7.jpg', 'Es una fragancia vibrante, seductora y con mucha presencia. Destaca por un contraste entre una salida fresca de menta, manzana verde y limón, que rápidamente da paso a un fondo cálido, dulce y envolvente dominado por la vainilla, el haba tonka y maderas de cedro. Es ideal para destacar en la noche, salidas informales o citas donde busques dejar huella.', '/img/eros/hero-eros.jpg', 'EL ALMA DE EROS', 'Eros nace del deseo de capturar la esencia fresca y floreciente de un jardín en plena floración. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Menta, se despliega en un corazón de Haba tonka y se asienta en una base de Vainilla de Madagascar, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/eros/fondo-notas.jpg', '/img/eros/fondo-cta.jpg', '/img/eros/fondo-seccion.jpg', 'Vive la Experiencia Eros', 'Descubre Eros de Versace, una fragancia fresca y floreciente hecha para dejar huella.', 0, NULL, '["poderoso"]', '["noche_especial","cita_romantica"]', '{"salida":["Menta","Manzana verde","Limon"],"corazon":["Haba tonka","Ambroxan","Geranio"],"fondo":["Vainilla de Madagascar","Cedro de virginia","Cedro del atlas","Vetiver","Musgo de roble"]}', '{"salida":"/img/eros/notas-salida.jpg","corazon":"/img/eros/notas-corazon.jpg","fondo":"/img/eros/notas-fondo.jpg"}', NULL, '{"tema-bg":"#00232c","tema-card":"#306f79","tema-dorado":"#c2a06a"}'),
  (6, 'LUX006', 125, 'Jean Paul Gaultier', 'Le Beau Le Parfum', 117990, 7, 2, 'moderados', 'gourmand', 'verano', 'hombre', 'disenador', 'edp', 'https://fimgs.net/photogram/p1200/ue/l8/0IZYXSzIvUm7OkMc.jpg', 'Es una fragancia exótica, ultra atractiva y densa que combina la frescura tropical con una base profundamente dulce y cálida. Su acorde estrella mezcla un coco cremoso y ahumado con madera de sándalo, tonka y un toque de piña jugosa. Es un aroma adictivo y de gran proyección, perfecto para noches de verano, salidas de fiesta o citas románticas donde busques destacar.', '/img/le-beau-le-parfum/hero-le-beau-le-parfum.jpg', 'EL ALMA DE LE BEAU LE PARFUM', 'Le Beau Le Parfum nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su lado más sensible con total confianza: una fragancia que se abre con Piña, se despliega en un corazón de Coco y se asienta en una base de Haba tonka, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/le-beau-le-parfum/fondo-notas.jpg', '/img/le-beau-le-parfum/fondo-cta.jpg', '/img/le-beau-le-parfum/fondo-seccion.jpg', 'Vive la Experiencia Le Beau Le Parfum', 'Descubre Le Beau Le Parfum de Jean Paul Gaultier, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["romantico","poderoso"]', '["playa","noche_especial","cita_romantica"]', '{"salida":["Piña","Iris","Jengibre","Cipres"],"corazon":["Coco","Notas amaderadas"],"fondo":["Haba tonka","Sandalo","Ambar","Ambar gris"]}', '{"salida":"/img/le-beau-le-parfum/notas-salida.jpg","corazon":"/img/le-beau-le-parfum/notas-corazon.jpg","fondo":"/img/le-beau-le-parfum/notas-fondo.jpg"}', NULL, '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (7, 'LUX007', 75, 'Parfums de Marly', 'Delina Exclusif', 364990, 12, 2, 'intensos', 'floral', 'primavera', 'mujer', 'nicho', 'parfum', 'https://fimgs.net/photogram/p1200/qq/ho/b5y2gJ4LoiKF58Qd.jpg', 'Delina Exclusif es una fragancia opulenta, sensual y extremadamente sofisticada. Toma el ADN de rosa y lichi del Delina original y lo lleva a un terreno más denso, cremoso y nocturno, incorporando notas sensuales de incienso, ámbar y una vainilla sumamente suave y abizcochada. Es un aroma elegante y envolvente con una fijación extraordinaria, concebido para ocasiones especiales donde quieras proyectar distinción y glamour absoluto..', '/img/delina-exclusif/hero-delina-exclusif.jpg', 'EL ALMA DE DELINA EXCLUSIF', 'Delina Exclusif nace del deseo de capturar la esencia fresca y floreciente de un jardín en plena floración. Creada para quien abraza su sofisticación natural con total confianza: una fragancia que se abre con Lichi, se despliega en un corazón de Rosa Turca y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/delina-exclusif/fondo-notas.jpg', '/img/delina-exclusif/fondo-cta.jpg', '/img/delina-exclusif/fondo-seccion.jpg', 'Vive la Experiencia Delina Exclusif', 'Descubre Delina Exclusif de Parfums de Marly, una fragancia fresca y floreciente hecha para dejar huella.', 1, NULL, '["elegante","romantico"]', '["noche_especial","evento_exclusivo","cita_romantica","gala","boda"]', '{"salida":["Lichi","Pera","Bergamota","Pimienta Rosa","Toronja"],"corazon":["Rosa Turca","Madera de oud","Incienso"],"fondo":["Vainilla","Ambar","Notas amaderadas","Almizcle","Evernil","Vetiver"]}', '{"salida":"/img/delina-exclusif/notas-salida.jpg","corazon":"/img/delina-exclusif/notas-corazon.jpg","fondo":"/img/delina-exclusif/notas-fondo.jpg"}', NULL, '{"tema-bg":"#fdf1f5","tema-card":"#f3d9e3","tema-dorado":"#c2a06a"}'),
  (8, 'LUX008', 50, 'Xerjoff', 'XJ 1861 Naxos', 219990, 3, 1, 'intensos', 'oriental', 'invierno', 'unisex', 'nicho', 'edp', 'https://fimgs.net/photogram/p1200/ks/63/viIeYrLTzoakkieZ.jpg', 'XJ 1861 Naxos de Xerjoff es un tributo a la riqueza y tradición de Sicilia, ofreciendo un aroma suntuoso, cálido y sumamente sofisticado. Destaca por una combinación magistral de miel dorada y tabaco dulce, equilibrada en su apertura por un toque brillante de lavanda y cítricos, para luego asentarse en una base cremosa de vainilla, haba tonka y canela. Es una fragancia versátil dentro de la alta perfumería, con presencia imponente pero extremadamente refinada, ideal para climas templados o fríos y eventos donde la elegancia sea protagonista.', '/img/xj-1861-naxos/hero-xj-1861-naxos.jpg', 'EL ALMA DE XJ 1861 NAXOS', 'XJ 1861 Naxos nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su sofisticación natural con total confianza: una fragancia que se abre con Lavanda, se despliega en un corazón de Miel y se asienta en una base de Hojas de tabaco, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/xj-1861-naxos/fondo-notas.jpg', '/img/xj-1861-naxos/fondo-cta.jpg', '/img/xj-1861-naxos/fondo-seccion.jpg', 'Vive la Experiencia XJ 1861 Naxos', 'Descubre XJ 1861 Naxos de Xerjoff, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["elegante","poderoso","misterioso"]', '["noche_especial","evento_exclusivo","cita_romantica","trabajo_reuniones","gala"]', '{"salida":["Lavanda","Bergamota","Limon"],"corazon":["Miel","Canela","Cachemira","Jazmin sambac"],"fondo":["Hojas de tabaco","Vainilla","Habatonka"]}', '{"salida":"/img/xj-1861-naxos/notas-salida.jpg","corazon":"/img/xj-1861-naxos/notas-corazon.jpg","fondo":"/img/xj-1861-naxos/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (9, 'LUX009', 100, 'Dumont', 'Nitro Red', 27990, 10, 2, 'intensos', 'frutal', 'verano', 'hombre', 'arabe', 'edp', 'https://fimgs.net/photogram/p1200/6g/8s/bZuLdAW7wKZY7PaH.jpg', 'Una fragancia vibrante, dulce y sumamente llamativa. Destaca por una salida muy frutal donde brilla una refrescante nota de sandía y manzana, para luego asentarse en un fondo amaderado y ambarino que le da mucha potencia. Con un rendimiento bestial, es ideal para destacar en climas cálidos, salidas informales o en la playa.', '/img/nitro-red/hero-nitro-red.jpg', 'EL ALMA DE NITRO RED', 'Nitro Red nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Manzana, se despliega en un corazón de Sandía y se asienta en una base de Ámbar, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/nitro-red/fondo-notas.jpg', '/img/nitro-red/fondo-cta.jpg', '/img/nitro-red/fondo-seccion.jpg', 'Vive la Experiencia Nitro Red', 'Descubre Nitro Red de Dumont, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","poderoso"]', '["playa","dia_a_dia","noche_especial"]', '{"salida":["Manzana","Lavanda","Bergamota"],"corazon":["Sandía","Cedro","Cálamo aromático"],"fondo":["Ámbar","Sándalo","Pachulí"]}', '{"salida":"/img/nitro-red/notas-salida.jpg","corazon":"/img/nitro-red/notas-corazon.jpg","fondo":"/img/nitro-red/notas-fondo.jpg"}', '{"marca":"Paco Rabanne","nombre":"Invictus","precioOriginal":109990}', '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (10, 'LUX010', 100, 'Dumont', 'Nitro Elixir', 28990, 10, 2, 'intensos', 'gourmand', 'otono', 'hombre', 'arabe', 'edp', 'https://beautyexpresspr.com/cdn/shop/files/645fd9fe-a616-4903-9be9-eefc94a6ef14.png?v=1778946349&width=1200', 'Una fragancia moderna y magnética. Su salida cítrica y especiada abre paso a un corazón sorprendente donde la flor de azahar se funde con el dulzor del praliné y el frescor de la menta. Su fondo cálido de ámbar y haba tonka le otorga una estela seductora, perfecta para la noche y ocasiones especiales.', '/img/nitro-elixir/hero-nitro-elixir.jpg', 'EL ALMA DE NITRO ELIXIR', 'Nitro Elixir nace del deseo de capturar la esencia profunda y envolvente de un atardecer de otoño. Creada para quien abraza su sofisticación natural con total confianza: una fragancia que se abre con Bergamota, se despliega en un corazón de Flor de azahar del naranjo y se asienta en una base de Ámbar gris, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/nitro-elixir/fondo-notas.jpg', '/img/nitro-elixir/fondo-cta.jpg', '/img/nitro-elixir/fondo-seccion.jpg', 'Vive la Experiencia Nitro Elixir', 'Descubre Nitro Elixir de Dumont, una fragancia profunda y envolvente hecha para dejar huella.', NULL, NULL, '["elegante","misterioso"]', '["noche_especial","cita_romantica"]', '{"salida":["Bergamota","Manzana","Cardamomo","Naranja"],"corazon":["Flor de azahar del naranjo","Praliné","Menta","Geranio"],"fondo":["Ámbar gris","Haba tonka","Ámbar","Musgo"]}', '{"salida":"/img/nitro-elixir/notas-salida.jpg","corazon":"/img/nitro-elixir/notas-corazon.jpg","fondo":"/img/nitro-elixir/notas-fondo.jpg"}', '{"marca":"Yves Saint Laurent","nombre":"MYSLF L''Absolu","precioOriginal":149990}', '{"tema-bg":"#2a1810","tema-card":"#4a2c1a","tema-dorado":"#c2a06a"}'),
  (11, 'LUX011', 100, 'Dumont', 'Nitro Gold', 37990, 10, 2, 'moderados', 'amaderado', 'primavera', 'unisex', 'arabe', 'edp', 'https://luxuryperfumesarabes.cl/wp-content/uploads/2026/06/2_8e58c6fd-39d8-4fb4-aeae-b39460a6b03d.webp', 'Una fragancia unisex versátil y cautivadora. Inicia con una explosión frutal y especiada de piña, cítricos y pimienta, que da paso a un corazón contrastante de notas marinas, sal y coñac. Su base cálida de vainilla, tófe y maderas ambaradas le aporta una estela elegante y muy duradera.', '/img/nitro-gold/hero-nitro-gold.jpg', 'EL ALMA DE NITRO GOLD', 'Nitro Gold nace del deseo de capturar la esencia fresca y floreciente de un jardín en plena floración. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Manzana, se despliega en un corazón de Sal y se asienta en una base de Amberwood, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/nitro-gold/fondo-notas.jpg', '/img/nitro-gold/fondo-cta.jpg', '/img/nitro-gold/fondo-seccion.jpg', 'Vive la Experiencia Nitro Gold', 'Descubre Nitro Gold de Dumont, una fragancia fresca y floreciente hecha para dejar huella.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","noche_especial"]', '{"salida":["Manzana","Pimienta rosa","Pimienta negra","Toronja (pomelo)","Piña","Naranja tangerina"],"corazon":["Sal","Notas marinas","Cedro","Coñac","Vetiver"],"fondo":["Amberwood","Sándalo","Almizcle","Tófe","Vainilla"]}', '{"salida":"/img/nitro-gold/notas-salida.jpg","corazon":"/img/nitro-gold/notas-corazon.jpg","fondo":"/img/nitro-gold/notas-fondo.jpg"}', '{"marca":"Valentino","nombre":"Valentino Uomo Born in Roma","precioOriginal":129990}', '{"tema-bg":"#fdf1f5","tema-card":"#f3d9e3","tema-dorado":"#c2a06a"}'),
  (12, 'LUX012', 100, 'Afnan', '9 PM Night Out', 42990, 10, 2, 'intensos', 'gourmand', 'invierno', 'unisex', 'arabe', 'edp', 'https://cosmetic.cl/cdn/shop/files/9_ab103946-5d5b-4a24-acc5-cbb0ef5e2583_800x.png?v=1769454599', 'Una fragancia nocturna, potente y seductora. Abre con una mezcla exótica de pitahaya y un toque embriagador de coñac, dando paso a un corazón cálido y dulce de tófe y gamuza. Su base rica en maderas y haba tonka garantiza una estela envolvente, ideal para dejar huella en la noche.', '/img/9pm-night-out/9pm-hero.jpg', 'El Llamado de la Medianoche', 'AFNAN nace de la pasión por capturar los momentos más intensos de la noche. 9 PM Night Out fue creado para el hombre que domina la oscuridad con confianza: una fragancia que se enciende como la ciudad al caer el sol y se despliega en cada encuentro, cada mirada, cada instante robado a la noche. Una firma olfativa pensada para quienes no solo salen de noche, sino que la hacen suya.', '/img/9pm-night-out/Fondonotas.jpg', '/img/9pm-night-out/cta-fondo.jpg', '/img/9pm-night-out/fondo_seccion.jpg', 'Vive la Experiencia 9 PM Night Out', 'Eleva tu presencia con una fragancia que habla por ti, hecha para dominar la noche.', NULL, 'contain', '["poderoso","misterioso"]', '["noche_especial","cita_romantica","evento_exclusivo"]', '{"salida":["Pitahaya","Lavanda","Coñac","Manzana","Bergamota"],"corazon":["Tófe","Gamuza","Cardamomo","Cedro","Mahonial"],"fondo":["Haba tonka","Akigalawood","Ambrofix™","Pachulí"]}', '{"salida":"/img/9pm-night-out/notas_salida.jpg","corazon":"/img/9pm-night-out/notas_corazon.jpg","fondo":"/img/9pm-night-out/notas_fondo.jpg"}', '{"marca":"Azzaro","nombre":"Forever Wanted Elixir","precioOriginal":75000}', '{"tema-bg":"#000000","tema-card":"#111111","tema-dorado":"#c2a06a"}'),
  (13, 'LUX013', 100, 'Hugo Boss', 'Boss The Scent Elixir For Him', 169990, 10, 2, 'intensos', 'especiado', 'invierno', 'hombre', 'disenador', 'parfum', 'https://i5.walmartimages.cl/asr/155346b3-27a0-4a88-83cb-fa37ab28fb5f.40bf4d6021871127eceef8b1a1e73c42.jpeg?odnHeight=612&odnWidth=612&odnBg=FFFFFF', 'Un elixir ardiente y altamente concentrado. Su apertura impacta con el calor vibrante del chile rojo, que se equilibra a la perfección con un corazón aromático de lavanda. Finalmente, descansa sobre una base rica y cremosa de sándalo, creando una estela seductora, cálida y profundamente masculina.', '/img/boss-the-scent-elixir-for-him/hero-boss-the-scent-elixir-for-him.jpg', 'EL ALMA DE BOSS THE SCENT ELIXIR FOR HIM', 'Boss The Scent Elixir For Him nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Chile rojo (ají rojo), se despliega en un corazón de Lavanda y se asienta en una base de Sándalo, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/boss-the-scent-elixir-for-him/fondo-notas.jpg', '/img/boss-the-scent-elixir-for-him/fondo-cta.jpg', '/img/boss-the-scent-elixir-for-him/fondo-seccion.jpg', 'Vive la Experiencia Boss The Scent Elixir For Him', 'Descubre Boss The Scent Elixir For Him de Hugo Boss, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","misterioso"]', '["noche_especial","cita_romantica"]', '{"salida":["Chile rojo (ají rojo)"],"corazon":["Lavanda"],"fondo":["Sándalo"]}', '{"salida":"/img/boss-the-scent-elixir-for-him/notas-salida.jpg","corazon":"/img/boss-the-scent-elixir-for-him/notas-corazon.jpg","fondo":"/img/boss-the-scent-elixir-for-him/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (14, 'LUX014', 125, 'Jean Paul Gaultier', 'Le Beau Paradise Garden', 153990, 10, 2, 'moderados', 'acuatico', 'verano', 'hombre', 'disenador', 'edp', 'https://media.falabella.com/falabellaCL/50369047_6/w=1500,h=1500,fit=cover', 'Una escapada a un jardín tropical. Abre con un frescor vibrante de notas verdes, menta y acordes acuosos. En su corazón, la mezcla exótica de coco e higo se realza con un toque de sal, aportando una cremosidad adictiva. Su fondo de haba tonka y sándalo lo envuelve en una estela seductora, ideal para días de verano y ocasiones relajadas.', '/img/jpgparadise/hero-paradise.jpg', 'EL DESPERTAR DEL PARAÍSO', 'Le Beau Paradise Garden nace del deseo de capturar la energía vibrante y exuberante de la primavera. Creada para el hombre que abraza su naturaleza más instintiva con total confianza: una fragancia que florece como un edén exótico bajo el sol de la mañana y se despliega en cada brisa acuática, cada nota de coco y cada instante robado en el jardín prohibido. Una firma olfativa pensada para quienes no solo exploran el paraíso, sino que se convierten en la tentación misma.', '/img/jpgparadise/fondo-notas.jpg', '/img/jpgparadise/fondo-cta.jpg', '/img/jpgparadise/fondo-seccion.jpg', 'Vive la Experiencia Paradise Garden', 'Eleva tu presencia con una fragancia vibrante y seductora, hecha para deslumbrar bajo el sol primaveral y despertar tus sentidos.', NULL, NULL, '["fresco","relajado"]', '["playa","dia_a_dia"]', '{"salida":["Notas verdes","Notas acuosas","Menta","Jengibre"],"corazon":["Coco","Higo","Sal"],"fondo":["Haba tonka","Sándalo"]}', '{"salida":"/img/jpgparadise/notas-salida.jpg","corazon":"/img/jpgparadise/notas-corazon.jpg","fondo":"/img/jpgparadise/notas-fondo.jpg"}', NULL, '{"tema-bg":"#fdefe0","tema-card":"#eadfc8","tema-dorado":"#c2a06a","tema-card-salida":"#f5f0eb","tema-card-corazon":"#f5f0eb","tema-card-fondo":"#f5f0eb"}'),
  (15, 'LUX015', 100, 'Giorgio Armani', 'Emporio Armani Stronger With You Intensely', 89990, 10, 2, 'intensos', 'gourmand', 'invierno', 'hombre', 'disenador', 'edp', 'https://cl-dam-resizer.ecomm.cencosud.com/unsafe/adaptive-fit-in/3840x0/filters:quality(75)/cl/paris/206934999/variant/685ac78315a03c31025e0564/images/baaecf13-ece0-4982-a957-76541918144d/206934999-0000-003.jpg', 'Una fragancia cálida, dulce y profundamente adictiva. Inicia con un toque especiado de pimienta rosa y enebro, envuelto en hojas de violeta. Su corazón irresistible combina la dulzura del tófe y la canela con destellos aromáticos, para finalmente fundirse en un fondo intenso de vainilla, ámbar y gamuza. Es el aroma perfecto para destacar en las noches frías y en citas románticas.', '/img/emporio-armani-stronger-with-you-intensely/hero-emporio-armani-stronger-with-you-intensely.jpg', 'EL ALMA DE EMPORIO ARMANI STRONGER WITH YOU INTENSELY', 'Emporio Armani Stronger With You Intensely nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su lado más sensible con total confianza: una fragancia que se abre con Pimienta rosa, se despliega en un corazón de Tófe y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/emporio-armani-stronger-with-you-intensely/fondo-notas.jpg', '/img/emporio-armani-stronger-with-you-intensely/fondo-cta.jpg', '/img/emporio-armani-stronger-with-you-intensely/fondo-seccion.jpg', 'Vive la Experiencia Emporio Armani Stronger With You Intensely', 'Descubre Emporio Armani Stronger With You Intensely de Giorgio Armani, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["romantico","poderoso"]', '["cita_romantica","noche_especial"]', '{"salida":["Pimienta rosa","Enebro","Violeta"],"corazon":["Tófe","Canela","Lavanda","Salvia"],"fondo":["Vainilla","Ámbar","Haba tonka","Gamuza"]}', '{"salida":"/img/emporio-armani-stronger-with-you-intensely/notas-salida.jpg","corazon":"/img/emporio-armani-stronger-with-you-intensely/notas-corazon.jpg","fondo":"/img/emporio-armani-stronger-with-you-intensely/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (16, 'LUX016', 100, 'Giorgio Armani', 'Power Of You', 96990, 10, 2, 'moderados', 'floral', 'verano', 'mujer', 'disenador', 'edp', 'https://media.falabella.com/falabellaCL/80711328_3/w=1500,h=1500,fit=cover', 'Una fragancia luminosa y tropical. Abre con la jugosidad exótica del maracuyá y vibrantes toques cítricos, dando paso a un corazón radiante de frangipani y notas solares. Su base cálida de vainilla de Madagascar y benjuí envuelve la piel con un toque dulce y elegante, perfecta para destacar en días soleados.', '/img/power-of-you/hero-power-of-you.jpg', 'EL ALMA DE POWER OF YOU', 'Power Of You nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Maracuyá (fruta de la pasión), se despliega en un corazón de Frangipani (plumeria, plumaria, atapaima) y se asienta en una base de Vainilla de Madagascar, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/power-of-you/fondo-notas.jpg', '/img/power-of-you/fondo-cta.jpg', '/img/power-of-you/fondo-seccion.jpg', 'Vive la Experiencia Power Of You', 'Descubre Power Of You de Giorgio Armani, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","playa"]', '{"salida":["Maracuyá (fruta de la pasión)","Naranja amarga","Limón (lima ácida)"],"corazon":["Frangipani (plumeria, plumaria, atapaima)","Notas solares"],"fondo":["Vainilla de Madagascar","Benjuí","Ládano"]}', '{"salida":"/img/power-of-you/notas-salida.jpg","corazon":"/img/power-of-you/notas-corazon.jpg","fondo":"/img/power-of-you/notas-fondo.jpg"}', NULL, '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (17, 'LUX017', 100, 'Jean Paul Gaultier', 'La Belle', 121950, 10, 2, 'intensos', 'avainillado', 'otono', 'mujer', 'disenador', 'edp', 'https://static.sweetcare.com/img/prd/488/v-638485379091938175/jean-paul-gaultier-011307jg-3.webp', 'Una fragancia irresistiblemente dulce y seductora. Abre con una nota jugosa y luminosa de pera entrelazada con bergamota, que se funde en un corazón cautivador de notas florales y un toque audaz de cuero. Su base es un adictivo abrazo de vainilla, ámbar, vetiver y almizcle, creando una estela femenina, sensual y perfecta para deslumbrar en ocasiones especiales.', '/img/la-belle/hero-la-belle.jpg', 'EL ALMA DE LA BELLE', 'La Belle nace del deseo de capturar la esencia profunda y envolvente de un atardecer de otoño. Creada para quien abraza su lado más sensible con total confianza: una fragancia que se abre con Pera, se despliega en un corazón de Notas florales y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/la-belle/fondo-notas.jpg', '/img/la-belle/fondo-cta.jpg', '/img/la-belle/fondo-seccion.jpg', 'Vive la Experiencia La Belle', 'Descubre La Belle de Jean Paul Gaultier, una fragancia profunda y envolvente hecha para dejar huella.', NULL, NULL, '["romantico","elegante"]', '["cita_romantica","noche_especial"]', '{"salida":["Pera","Bergamota"],"corazon":["Notas florales","Cuero"],"fondo":["Vainilla","Vetiver","Ámbar","Almizcle"]}', '{"salida":"/img/la-belle/notas-salida.jpg","corazon":"/img/la-belle/notas-corazon.jpg","fondo":"/img/la-belle/notas-fondo.jpg"}', NULL, '{"tema-bg":"#2a1810","tema-card":"#4a2c1a","tema-dorado":"#c2a06a"}'),
  (18, 'LUX018', 80, 'Carolina Herrera', 'Good Girl', 109990, 10, 2, 'intensos', 'oriental', 'invierno', 'mujer', 'disenador', 'edp', 'https://productosdelujo.cl/cdn/shop/products/3CC24099563.jpg?v=1623701251&width=1214', 'Una fragancia audaz y sofisticada, símbolo de la dualidad femenina. Abre con notas luminosas de almendra y un toque energizante de café. El corazón es un bouquet floral de nardos y jazmín sambac que irradia feminidad, mientras que su fondo profundo y seductor revela notas sumamente adictivas de haba tonka, cacao y vainilla. Perfecta para empoderar tus noches y eventos exclusivos.', '/img/good-girl/hero-good-girl.jpg', 'EL ALMA DE GOOD GIRL', 'Good Girl nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Almendra, se despliega en un corazón de Nardos y se asienta en una base de Haba tonka, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/good-girl/fondo-notas.jpg', '/img/good-girl/fondo-cta.jpg', '/img/good-girl/fondo-seccion.jpg', 'Vive la Experiencia Good Girl', 'Descubre Good Girl de Carolina Herrera, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","misterioso","elegante"]', '["noche_especial","cita_romantica"]', '{"salida":["Almendra","Café","Bergamota","Limón (lima ácida)"],"corazon":["Nardos","Jazmín sambac (sampaguita)","Flor de azahar del naranjo","Rosa de Bulgaria (rosa Damascena de Bulgaria)","Raíz de lirio"],"fondo":["Haba tonka","Cacao","Vainilla","Praliné","Sándalo","Almizcle","Ámbar","Madera de cachemira","Pachulí","Canela","Cedro"]}', '{"salida":"/img/good-girl/notas-salida.jpg","corazon":"/img/good-girl/notas-corazon.jpg","fondo":"/img/good-girl/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (19, 'LUX019', 100, 'Louis Vuitton', 'L''Immensité', 462000, 10, 2, 'moderados', 'acuatico', 'verano', 'hombre', 'nicho', 'edp', 'https://la.louisvuitton.com/images/is/image/lv/1/PP_VP_L/louis-vuitton-perfume-l-immensite--LP0052_PM1_Interior%20view.jpg', 'Una fragancia refrescante y sofisticada de alta gama. Su apertura vibrante de toronja y jengibre da paso a un corazón aromático y acuático. El fondo de ambroxan y ámbar asegura una estela elegante y persistente, ideal para proyectar exclusividad y frescura en el día a día.', '/img/limmensite/hero-limmensite.jpg', 'EL ALMA DE L''IMMENSITÉ', 'L''Immensité nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Toronja (pomelo), se despliega en un corazón de Romero y se asienta en una base de Ambroxan, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/limmensite/fondo-notas.jpg', '/img/limmensite/fondo-cta.jpg', '/img/limmensite/fondo-seccion.jpg', 'Vive la Experiencia L''Immensité', 'Descubre L''Immensité de Louis Vuitton, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","trabajo_reuniones","evento_exclusivo"]', '{"salida":["Toronja (pomelo)","Bergamota","Jengibre"],"corazon":["Romero","Salvia","Geranio","Notas acuáticas"],"fondo":["Ambroxan","Ámbar","Ládano"]}', '{"salida":"/img/limmensite/notas-salida.jpg","corazon":"/img/limmensite/notas-corazon.jpg","fondo":"/img/limmensite/notas-fondo.jpg"}', NULL, '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (20, 'LUX020', 100, 'Louis Vuitton', 'Imagination', 420000, 10, 2, 'moderados', 'citrico', 'verano', 'hombre', 'nicho', 'edp', 'https://la.louisvuitton.com/images/is/image/lv/1/PP_VP_L/louis-vuitton-perfume-imagination--LP0219_PM1_Interior%20view.jpg', 'Una obra maestra cítrica y estimulante. Abre con un estallido luminoso de cítricos italianos, evolucionando hacia un corazón especiado de neroli y jengibre. La magia ocurre en su fondo, donde el té negro de China y el ambroxan crean un aura limpia, lujosa y sumamente adictiva.', '/img/imagination/hero-imagination.jpg', 'EL ALMA DE IMAGINATION', 'Imagination nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Cidra, se despliega en un corazón de Neroli de Túnez y se asienta en una base de Té negro de China, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/imagination/fondo-notas.jpg', '/img/imagination/fondo-cta.jpg', '/img/imagination/fondo-seccion.jpg', 'Vive la Experiencia Imagination', 'Descubre Imagination de Louis Vuitton, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","elegante","relajado"]', '["dia_a_dia","trabajo_reuniones","playa"]', '{"salida":["Cidra","Bergamota de Calabria","Naranja siciliana"],"corazon":["Neroli de Túnez","Jengibre nigeriano","Canela de Ceylan"],"fondo":["Té negro de China","Ambroxan","Madera de gaiac","Incienso de olíbano (franquincienso)"]}', '{"salida":"/img/imagination/notas-salida.jpg","corazon":"/img/imagination/notas-corazon.jpg","fondo":"/img/imagination/notas-fondo.jpg"}', NULL, '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (21, 'LUX021', 100, 'Arabiyat Prestige', 'Marwa', 39990, 10, 2, 'moderados', 'citrico', 'verano', 'hombre', 'arabe', 'edp', 'https://http2.mlstatic.com/D_NQ_NP_751711-CBT110859757181_042026-O.webp', 'Una fragancia vibrante, fresca y sumamente limpia. Abre con un cóctel cítrico brillante, dando paso a un corazón ligeramente especiado de jengibre y canela. Su fondo de té negro y ambroxan le otorga un aura elegante y magnética, ideal para brillar durante el día y en el trabajo.', '/img/marwa/hero-marwa.jpg', 'EL ALMA DE MARWA', 'Marwa nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Bergamota de Calabria, se despliega en un corazón de Jengibre nigeriano y se asienta en una base de Ambroxan, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/marwa/fondo-notas.jpg', '/img/marwa/fondo-cta.jpg', '/img/marwa/fondo-seccion.jpg', 'Vive la Experiencia Marwa', 'Descubre Marwa de Arabiyat Prestige, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","trabajo_reuniones"]', '{"salida":["Bergamota de Calabria","Limón (lima ácida)","Naranja siciliana"],"corazon":["Jengibre nigeriano","Canela de Ceylan","Neroli de Túnez"],"fondo":["Ambroxan","Té negro de China","Incienso de olíbano (franquincienso)","Madera de gaiac"]}', '{"salida":"/img/marwa/notas-salida.jpg","corazon":"/img/marwa/notas-corazon.jpg","fondo":"/img/marwa/notas-fondo.jpg"}', '{"marca":"Louis Vuitton","nombre":"Imagination","precioOriginal":420000}', '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (22, 'LUX022', 50, 'Tom Ford', 'Lost Cherry', 384990, 10, 2, 'intensos', 'frutal', 'otono', 'unisex', 'nicho', 'edp', 'https://hypefragrances.cl/wp-content/uploads/2021/11/LOST-CHERRY-2.jpg', 'Un viaje olfativo exótico, cálido y profundamente dulce. Abre con una explosión intensa de cereza negra, licor y almendra amarga, que se funde en un corazón de ciruela y notas florales. Su fondo es una mezcla opulenta de vainilla, haba tonka y maderas preciosas que crean una estela embriagadora e irresistible.', '/img/lost-cherry/hero-lost-cherry.jpg', 'EL ALMA DE LOST CHERRY', 'Lost Cherry nace del deseo de capturar la esencia profunda y envolvente de un atardecer de otoño. Creada para quien abraza su aura enigmática con total confianza: una fragancia que se abre con Almendra amarga, se despliega en un corazón de Cereza ácida (guinda) y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/lost-cherry/fondo-notas.jpg', '/img/lost-cherry/fondo-cta.jpg', '/img/lost-cherry/fondo-seccion.jpg', 'Vive la Experiencia Lost Cherry', 'Descubre Lost Cherry de Tom Ford, una fragancia profunda y envolvente hecha para dejar huella.', NULL, NULL, '["misterioso","elegante"]', '["noche_especial","cita_romantica","evento_exclusivo"]', '{"salida":["Almendra amarga","Cereza negra","Licor de cereza"],"corazon":["Cereza ácida (guinda)","Ciruela","Rosa turca","Jazmín sambac (sampaguita)"],"fondo":["Vainilla","Haba tonka","Canela","Bálsamo del Perú","Sándalo","Benjuí","Clavos de olor","Cedro","Pachulí","Vetiver"]}', '{"salida":"/img/lost-cherry/notas-salida.jpg","corazon":"/img/lost-cherry/notas-corazon.jpg","fondo":"/img/lost-cherry/notas-fondo.jpg"}', NULL, '{"tema-bg":"#2a1810","tema-card":"#4a2c1a","tema-dorado":"#c2a06a"}'),
  (23, 'LUX023', 200, 'Versace', 'Eros Flame', 75990, 10, 2, 'intensos', 'especiado', 'invierno', 'hombre', 'disenador', 'edp', 'https://aliss.do/media/catalog/product/4/9/498e733a0af2fe685b95f8fbd46c0c9477d15eda_file.jpg?optimize=medium&bg-color=255,255,255&fit=bounds&height=700&width=700&canvas=700:700', 'Una fragancia apasionada, cálida y de contrastes. Abre con un golpe cítrico y especiado vibrante gracias a la mandarina y la pimienta negra, para luego revelar un corazón floral intenso. Su base cálida de vainilla, haba tonka y maderas nobles deja una estela poderosa y seductora, perfecta para climas fríos y ocasiones especiales.', '/img/eros-flame/hero-eros-flame.jpg', 'EL ALMA DE EROS FLAME', 'Eros Flame nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Mandarina, se despliega en un corazón de Geranio y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/eros-flame/fondo-notas.jpg', '/img/eros-flame/fondo-cta.jpg', '/img/eros-flame/fondo-seccion.jpg', 'Vive la Experiencia Eros Flame', 'Descubre Eros Flame de Versace, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","romantico"]', '["cita_romantica","noche_especial"]', '{"salida":["Mandarina","Pimienta de Madagascar","Limón (lima ácida)","Chinotto","Romero"],"corazon":["Geranio","Rosa","Pepperwood™"],"fondo":["Vainilla","Haba tonka","Sándalo","Cedro de Texas","Pachulí","Musgo de roble"]}', '{"salida":"/img/eros-flame/notas-salida.jpg","corazon":"/img/eros-flame/notas-corazon.jpg","fondo":"/img/eros-flame/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (24, 'LUX024', 100, 'Armaf', 'Odyssey Mandarin Sky', 34990, 10, 2, 'intensos', 'gourmand', 'otono', 'hombre', 'arabe', 'edp', 'https://perfumeschile.cl/cdn/shop/files/Odyssey-Mandarin-Sky-3.jpg?v=1787240368&width=600', 'Una fragancia dulce, jugosa y sumamente adictiva. Su salida explosiva de mandarina y naranja se funde rápidamente con un corazón deliciosamente gourmand de caramelo derretido y haba tonka. El fondo de ambroxan y maderas le da un soporte sólido y una proyección bestial, ideal para destacar tanto en salidas nocturnas como en días frescos.', '/img/odyssey-mandarin-sky/hero-odyssey-mandarin-sky.jpg', 'EL ALMA DE ODYSSEY MANDARIN SKY', 'Odyssey Mandarin Sky nace del deseo de capturar la esencia profunda y envolvente de un atardecer de otoño. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Mandarina, se despliega en un corazón de Caramelo y se asienta en una base de Ambroxan, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/odyssey-mandarin-sky/fondo-notas.jpg', '/img/odyssey-mandarin-sky/fondo-cta.jpg', '/img/odyssey-mandarin-sky/fondo-seccion.jpg', 'Vive la Experiencia Odyssey Mandarin Sky', 'Descubre Odyssey Mandarin Sky de Armaf, una fragancia profunda y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","relajado"]', '["noche_especial","dia_a_dia"]', '{"salida":["Mandarina","Naranja","Azafrán","Salvia"],"corazon":["Caramelo","Haba tonka","Cempasúchil (tagete, clavelón)"],"fondo":["Ambroxan","Cedro","Vetiver"]}', '{"salida":"/img/odyssey-mandarin-sky/notas-salida.jpg","corazon":"/img/odyssey-mandarin-sky/notas-corazon.jpg","fondo":"/img/odyssey-mandarin-sky/notas-fondo.jpg"}', '{"marca":"Jean Paul Gaultier","nombre":"Scandal Pour Homme","precioOriginal":110000}', '{"tema-bg":"#2a1810","tema-card":"#4a2c1a","tema-dorado":"#c2a06a"}'),
  (25, 'LUX025', 150, 'Jean Paul Gaultier', 'Scandal Pour Homme', 124990, 10, 2, 'intensos', 'gourmand', 'invierno', 'hombre', 'disenador', 'edt', 'https://cl-dam-resizer.ecomm.cencosud.com/unsafe/adaptive-fit-in/3840x0/filters:quality(75)/paris/517296999/variant/images/00056e7c-4391-4c76-bdfe-4b5f642cddd7/517296999-0000-003.jpg', 'Una fragancia magnética, dulce y audaz. Abre con un toque fresco y aromático de mandarina y esclarea, que rápidamente cede el paso a un corazón adictivo y goloso de caramelo y haba tonka. Su base de vetiver le otorga un anclaje terroso y masculino, creando una estela irresistible perfecta para la noche, fiestas y citas románticas.', '/img/scandal-pour-homme/hero-scandal-pour-homme.jpg', 'EL ALMA DE SCANDAL POUR HOMME', 'Scandal Pour Homme nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Mandarina, se despliega en un corazón de Caramelo y se asienta en una base de Vetiver, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/scandal-pour-homme/fondo-notas.jpg', '/img/scandal-pour-homme/fondo-cta.jpg', '/img/scandal-pour-homme/fondo-seccion.jpg', 'Vive la Experiencia Scandal Pour Homme', 'Descubre Scandal Pour Homme de Jean Paul Gaultier, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","romantico"]', '["noche_especial","cita_romantica"]', '{"salida":["Mandarina","Esclarea"],"corazon":["Caramelo","Haba tonka"],"fondo":["Vetiver"]}', '{"salida":"/img/scandal-pour-homme/notas-salida.jpg","corazon":"/img/scandal-pour-homme/notas-corazon.jpg","fondo":"/img/scandal-pour-homme/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (26, 'LUX026', 200, 'Paco Rabanne', 'Invictus Victory', 119990, 10, 2, 'intensos', 'oriental', 'invierno', 'hombre', 'disenador', 'edp', 'https://cl-dam-resizer.ecomm.cencosud.com/unsafe/adaptive-fit-in/3840x0/filters:quality(75)/cl/paris/724216999/variant/69c528b46a2ef0119c97fc2d/images/e2f18eb2-70ad-40cb-bcb1-4ee8c375cd44/724216999-0000-004.jpg', 'Una fragancia intensa, dulce y sumamente cautivadora. Abre con un contraste vibrante de limón y pimienta rosa, que da paso a un corazón misterioso de incienso y lavanda. Su fondo revela una calidez magnética con vainilla, haba tonka y ámbar, creando una estela poderosa y seductora, perfecta para la noche y climas fríos.', '/img/invictus-victory/hero-invictus-victory.jpg', 'EL ALMA DE INVICTUS VICTORY', 'Invictus Victory nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Pimienta rosa, se despliega en un corazón de Incienso de olíbano (franquincienso) y se asienta en una base de Vainilla, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/invictus-victory/fondo-notas.jpg', '/img/invictus-victory/fondo-cta.jpg', '/img/invictus-victory/fondo-seccion.jpg', 'Vive la Experiencia Invictus Victory', 'Descubre Invictus Victory de Paco Rabanne, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","misterioso"]', '["noche_especial","cita_romantica"]', '{"salida":["Pimienta rosa","Limón (lima ácida)"],"corazon":["Incienso de olíbano (franquincienso)","Lavanda"],"fondo":["Vainilla","Haba tonka","Ámbar"]}', '{"salida":"/img/invictus-victory/notas-salida.jpg","corazon":"/img/invictus-victory/notas-corazon.jpg","fondo":"/img/invictus-victory/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (27, 'LUX027', 100, 'Rayhaan', 'Wolf', 36000, 10, 2, 'intensos', 'gourmand', 'invierno', 'hombre', 'arabe', 'edp', 'https://yauras.cl/cdn/shop/files/There_sadifferencebetweenbeingseen_.andbeingremembered.Onefades.....andtheotherstays_525x700.webp?v=1779811334', 'Una fragancia cálida, dulce y sumamente seductora. Su apertura especiada de cardamomo capta la atención de inmediato, dando paso a un corazón goloso e irresistible de tófe. El fondo de amberwood le otorga profundidad, potencia y una duración excepcional, convirtiéndola en el arma perfecta para citas y noches de invierno.', '/img/wolf/hero-wolf.jpg', 'EL ALMA DE WOLF', 'Wolf nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Cardamomo, se despliega en un corazón de Tófe y se asienta en una base de Amberwood, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/wolf/fondo-notas.jpg', '/img/wolf/fondo-cta.jpg', '/img/wolf/fondo-seccion.jpg', 'Vive la Experiencia Wolf', 'Descubre Wolf de Rayhaan, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","misterioso"]', '["noche_especial","cita_romantica"]', '{"salida":["Cardamomo"],"corazon":["Tófe"],"fondo":["Amberwood"]}', '{"salida":"/img/wolf/notas-salida.jpg","corazon":"/img/wolf/notas-corazon.jpg","fondo":"/img/wolf/notas-fondo.jpg"}', '{"marca":"Azzaro","nombre":"The Most Wanted","precioOriginal":89990}', '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (28, 'LUX028', 100, 'Rayhaan', 'Tropical Vibe', 25990, 10, 2, 'moderados', 'frutal', 'verano', 'unisex', 'arabe', 'edp', 'https://www.lodoro.cl/cdn/shop/files/01CACYIAMBLOUPEPWS2050_81_1024x.png?v=1778598697', 'Un cóctel tropical embotellado. Abre con una jugosa mezcla de mango, piña y un toque embriagador de ron, evocando instantáneamente un ambiente festivo. Su corazón aporta cremosidad con coco y brisa salada, mientras que el fondo de almizcle y sándalo prolonga la sensación de piel cálida bajo el sol. Ideal para vacaciones y días calurosos.', '/img/tropical-vibe/hero-tropical-vibe.jpg', 'EL ALMA DE TROPICAL VIBE', 'Tropical Vibe nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Mango, se despliega en un corazón de Coco y se asienta en una base de Almizcle, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/tropical-vibe/fondo-notas.jpg', '/img/tropical-vibe/fondo-cta.jpg', '/img/tropical-vibe/fondo-seccion.jpg', 'Vive la Experiencia Tropical Vibe', 'Descubre Tropical Vibe de Rayhaan, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["fresco","relajado"]', '["playa","dia_a_dia"]', '{"salida":["Mango","Piña","Bergamota","Ron"],"corazon":["Coco","Flores blancas","Notas marinas"],"fondo":["Almizcle","Ámbar","Sándalo","Vetiver"]}', '{"salida":"/img/tropical-vibe/notas-salida.jpg","corazon":"/img/tropical-vibe/notas-corazon.jpg","fondo":"/img/tropical-vibe/notas-fondo.jpg"}', '{"marca":"Lorenzo Pazzaglia","nombre":"Summer Hammer","precioOriginal":158000}', '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (29, 'LUX029', 50, 'Lorenzo Pazzaglia', 'Summer Hammer', 158000, 10, 2, 'intensos', 'frutal', 'verano', 'unisex', 'nicho', 'parfum', 'https://odorare.fr/cdn/shop/files/summer-hammer-lorenzo-pazzaglia-extrait-de-parfum-50ml-ambiance-tropicale_4b09825c-f5a2-4569-86d2-cddb4a6f989c.png?v=1784465904&width=1254', 'Una experiencia olfativa de lujo absoluta que captura la esencia del verano eterno. Este extracto de perfume abre con una opulenta y densa mezcla de frutas exóticas bañadas en ron blanco. Su corazón revela una textura cremosa de leche de coco entrelazada con acordes salados, descansando sobre una base rica en ámbar y sándalo. Su rendimiento es extraordinario, proyectando una vibra tropical sofisticada y persistente.', '/img/summer-hammer/hero-summer-hammer.jpg', 'EL ALMA DE SUMMER HAMMER', 'Summer Hammer nace del deseo de capturar la esencia luminosa y vibrante de un día de verano bajo el sol. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Mango, se despliega en un corazón de Leche de coco y se asienta en una base de Almizcle, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/summer-hammer/fondo-notas.jpg', '/img/summer-hammer/fondo-cta.jpg', '/img/summer-hammer/fondo-seccion.jpg', 'Vive la Experiencia Summer Hammer', 'Descubre Summer Hammer de Lorenzo Pazzaglia, una fragancia luminosa y vibrante hecha para dejar huella.', 1, NULL, '["poderoso","relajado"]', '["playa","evento_exclusivo","noche_especial"]', '{"salida":["Mango","Piña","Coco","Bergamota","Ron blanco"],"corazon":["Leche de coco","Flores blancas","Notas marinas"],"fondo":["Almizcle","Sándalo","Ámbar","Vetiver"]}', '{"salida":"/img/summer-hammer/notas-salida.jpg","corazon":"/img/summer-hammer/notas-corazon.jpg","fondo":"/img/summer-hammer/notas-fondo.jpg"}', NULL, '{"tema-bg":"#eaf6fb","tema-card":"#cfe9f0","tema-dorado":"#c2a06a"}'),
  (30, 'LUX030', 100, 'Dior', 'Sauvage Elixir', 229990, 10, 2, 'intensos', 'especiado', 'invierno', 'hombre', 'disenador', 'parfum', 'https://media.falabella.com/falabellaCL/50190731_7/w=1500,h=1500,fit=cover', 'Una reinterpretación audaz y sumamente concentrada. Abre con un golpe cálido y especiado de nuez moscada, canela y cardamomo, contrastado con la frescura de la toronja. Su corazón puro de lavanda descansa sobre un fondo oscuro y opulento de regaliz, sándalo y ámbar. Es una fragancia imponente, de duración extrema, diseñada para dejar huella en la noche.', '/img/sauvage-elixir/hero-sauvage-elixir.jpg', 'EL ALMA DE SAUVAGE ELIXIR', 'Sauvage Elixir nace del deseo de capturar la esencia cálida y envolvente de una noche fría e íntima. Creada para quien abraza su instinto y carácter con total confianza: una fragancia que se abre con Nuez moscada, se despliega en un corazón de Lavanda y se asienta en una base de Regaliz, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/sauvage-elixir/fondo-notas.jpg', '/img/sauvage-elixir/fondo-cta.jpg', '/img/sauvage-elixir/fondo-seccion.jpg', 'Vive la Experiencia Sauvage Elixir', 'Descubre Sauvage Elixir de Dior, una fragancia cálida y envolvente hecha para dejar huella.', NULL, NULL, '["poderoso","misterioso","elegante"]', '["noche_especial","evento_exclusivo"]', '{"salida":["Nuez moscada","Canela","Cardamomo","Toronja (pomelo)"],"corazon":["Lavanda"],"fondo":["Regaliz","Sándalo","Ámbar","Pachulí","Vetiver de Haití"]}', '{"salida":"/img/sauvage-elixir/notas-salida.jpg","corazon":"/img/sauvage-elixir/notas-corazon.jpg","fondo":"/img/sauvage-elixir/notas-fondo.jpg"}', NULL, '{"tema-bg":"#0d1420","tema-card":"#1a2230","tema-dorado":"#c2a06a"}'),
  (31, 'LUX031', 100, 'Xerjoff', 'Erba Pura', 199990, 10, 2, 'intensos', 'frutal', 'primavera', 'unisex', 'nicho', 'edp', 'https://fenixperfumes.cl/cdn/shop/files/xerjoff-erba-pura-ultra-lujoso.png?v=1769030518', 'Una exquisita y moderna mezcla de cítricos mediterráneos dulces envueltos en un aura de lujo. Su salida vibrante de naranja y bergamota da paso a un corazón sumamente jugoso y frutal. El secreto de su estela inmensa radica en su fondo de almizcle blanco, ámbar y vainilla, creando una fragancia aterciopelada, brillante y adictiva.', '/img/erba-pura/hero-erba-pura.jpg', 'EL ALMA DE ERBA PURA', 'Erba Pura nace del deseo de capturar la esencia fresca y floreciente de un jardín en plena floración. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Naranja siciliana, se despliega en un corazón de Frutas y se asienta en una base de Almizcle blanco, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/erba-pura/fondo-notas.jpg', '/img/erba-pura/fondo-cta.jpg', '/img/erba-pura/fondo-seccion.jpg', 'Vive la Experiencia Erba Pura', 'Descubre Erba Pura de Xerjoff, una fragancia fresca y floreciente hecha para dejar huella.', 1, NULL, '["fresco","elegante"]', '["dia_a_dia","evento_exclusivo"]', '{"salida":["Naranja siciliana","Bergamota de Calabria","Limón siciliano (lima siciliana)"],"corazon":["Frutas"],"fondo":["Almizcle blanco","Vainilla de Madagascar","Ámbar"]}', '{"salida":"/img/erba-pura/notas-salida.jpg","corazon":"/img/erba-pura/notas-corazon.jpg","fondo":"/img/erba-pura/notas-fondo.jpg"}', NULL, '{"tema-bg":"#fdf1f5","tema-card":"#f3d9e3","tema-dorado":"#c2a06a"}'),
  (32, 'LUX032', 100, 'Valentino', 'Valentino Uomo Born In Roma Coral Fantasy', 159900, 10, 2, 'moderados', 'amaderado', 'otono', 'hombre', 'disenador', 'edt', 'https://i0.wp.com/dperfumes.cl/wp-content/uploads/2024/04/Valentino-Uomo-Born-In-Roma-Coral-Fantasy-Eau-de-Toilette-01.webp?fit=1200%2C1200&ssl=1', 'Una fragancia vibrante y de grandes contrastes. Abre con un acorde jugoso y llamativo de manzana roja entrelazado con cardamomo y bergamota. Su corazón aromático de lavanda y geranio descansa sobre una base profunda y sumamente masculina de hojas de tabaco y vetiver. Un aroma ideal para destacar con un toque moderno, seductor y atrevido.', '/img/valentino-uomo-born-in-roma-coral-fantasy/hero-valentino-uomo-born-in-roma-coral-fantasy.jpg', 'EL ALMA DE VALENTINO UOMO BORN IN ROMA CORAL FANTASY', 'Valentino Uomo Born In Roma Coral Fantasy nace del deseo de capturar la esencia profunda y envolvente de un atardecer de otoño. Creada para quien abraza su energía renovada con total confianza: una fragancia que se abre con Manzana roja, se despliega en un corazón de Lavanda y se asienta en una base de Hojas de tabaco, dejando una estela inolvidable. Una firma olfativa pensada para quienes no solo la usan, sino que la convierten en su sello personal.', '/img/valentino-uomo-born-in-roma-coral-fantasy/fondo-notas.jpg', '/img/valentino-uomo-born-in-roma-coral-fantasy/fondo-cta.jpg', '/img/valentino-uomo-born-in-roma-coral-fantasy/fondo-seccion.jpg', 'Vive la Experiencia Valentino Uomo Born In Roma Coral Fantasy', 'Descubre Valentino Uomo Born In Roma Coral Fantasy de Valentino, una fragancia profunda y envolvente hecha para dejar huella.', NULL, NULL, '["fresco","romantico"]', '["dia_a_dia","cita_romantica"]', '{"salida":["Manzana roja","Cardamomo","Bergamota de Calabria"],"corazon":["Lavanda","Geranio bourbon","Esclarea"],"fondo":["Hojas de tabaco","Pachulí","Vetiver de Haití"]}', '{"salida":"/img/valentino-uomo-born-in-roma-coral-fantasy/notas-salida.jpg","corazon":"/img/v